/**
 * Compatibility Matrix page.
 *
 * Renders the committed `ui/compat.lock.json` (component × adapter
 * compile-compatibility, generated by the repo-internal `packages/compat`
 * tool) as a docs page. The lock file is imported at build time so it is
 * bundled into the Worker — never read from disk at request time.
 *
 * Content is generated as a Markdown string and run through the site's
 * standard `renderMarkdown` pipeline so it gets the same heading IDs,
 * TOC extraction, and table styling as every other docs page, instead of
 * hand-rolling HTML/JSX.
 */

import type { Hono } from 'hono'
import { renderMarkdown } from '../lib/markdown'
import { getDocsNavLinks } from '../lib/navigation'
import lock from '../../../ui/compat.lock.json' with { type: 'json' }
import supportMatrixLock from '../../../ui/support-matrix.lock.json' with { type: 'json' }

const SLUG = 'advanced/compatibility-matrix'
const TITLE = 'Compatibility Matrix'
const DESCRIPTION = 'Compile-compatibility of every ui/ component across template adapters.'

interface CompatDiagnostic {
  code: string
  severity: 'error' | 'warning'
  issues?: string[]
  escapes?: string[]
}

/**
 * Canonical, enum-generated wording for each escape kind, with its SSR
 * cost (#2614 increment 2). Rendered in the LEGEND, never in a cell: a
 * cell aggregates adapters whose prose for the same code differs, and
 * surfacing that variance would export an internal inconsistency — by the
 * time an escape reaches this page it is one wording from one place.
 *
 * Mirrors `EscapeKind` / `ESCAPE_SSR_COST` (`packages/jsx/src/types.ts`).
 * The page deliberately re-declares rather than imports — `@barefootjs/jsx`
 * is not a runtime dependency of the site Worker, and every other compat
 * type here is mirrored the same way — so
 * `escape-legend-parity.test.ts` pins this map against the compiler's
 * union: a new kind there fails the test here rather than silently
 * rendering as a bare slug.
 */
export const ESCAPE_LABELS: Record<string, string> = {
  'prop-precompute': 'pass the computed result as a prop (full SSR)',
  'client-directive': '`/* @client */` (client-render; no SSR content until hydration)',
  rewrite: 'rewrite into an in-subset shape (full SSR)',
}

/**
 * Render a diagnostic's claimed escapes for the legend. Order is the
 * lock's (sorted) order re-sorted by SSR cost — a full-SSR way out is
 * listed before a client-render one, matching the prose rule that the
 * escape which keeps server content is offered first. Unknown kinds are
 * dropped rather than rendered raw; the parity test is what makes that
 * safe to do silently.
 */
function formatEscapes(escapes: string[] | undefined): string {
  if (!escapes?.length) return ''
  const known = escapes.filter((kind) => kind in ESCAPE_LABELS)
  if (known.length === 0) return ''
  const ssrFirst = [...known].sort((a, b) => {
    const cost = (kind: string) => (kind === 'client-directive' ? 1 : 0)
    return cost(a) - cost(b) || a.localeCompare(b)
  })
  return `escapes: ${ssrFirst.map((kind) => ESCAPE_LABELS[kind]).join(', ')}`
}

interface CompatCell {
  ok: boolean
  diagnostics?: CompatDiagnostic[]
}

/**
 * A refusal cell's escape state (#2613) — distinguishes a refusal with a
 * VERIFIED working escape (`'escapable'`, e.g. a `/* @client *\/` twin
 * that actually compiles clean on this adapter) from one that's still
 * tracked debt (`'debt'`, an adapter-declared `unescapable` pin) or that
 * owes no escape at all, by design (`'not-owed'`). Mirrors
 * `FixtureEscapeState` in `packages/compat/src/escape-coverage.ts`. Set
 * only on `'refusal'`-kind cells that are in the "loud-or-escapable"
 * floor's domain (an error-severity pin, on a fixture the reference
 * adapter doesn't itself refuse) — absent otherwise.
 */
type FixtureEscapeState = { state: 'escapable'; twin: string } | { state: 'debt' } | { state: 'not-owed'; reason: string }

interface FixtureDivergenceCell {
  kind: 'refusal' | 'render'
  codes?: string[]
  issues?: string[]
  reason?: string
  escape?: FixtureEscapeState
}

interface FixtureDoc {
  description: string
  url: string
}

interface FixtureDivergences {
  note: string
  totalFixtures: number
  fixtures: Record<string, Record<string, FixtureDivergenceCell>>
  /** Optional: fixture id → description + source link (older locks lack it). */
  docs?: Record<string, FixtureDoc>
}

interface ComponentDoc {
  title: string
  description: string
  url: string
  /** Optional: public component page on ui.barefootjs.dev (absent for components with no routed page). */
  uiUrl?: string
}

interface CompatLock {
  note: string
  knownLimitationLabel: string
  adapters: string[]
  components: Record<string, Record<string, CompatCell>>
  /** Optional: component name → title + description + source link (older locks lack it). */
  componentDocs?: Record<string, ComponentDoc>
  /** Optional: locks generated before #2168's render-honesty section lack it. */
  fixtureDivergences?: FixtureDivergences
}

const compat = lock as CompatLock

/** One `kind` or `axis` construct's covering-fixture total and its per-adapter cells (`ui/support-matrix.lock.json`). */
interface SupportMatrixGap {
  fixture: string
  issues: string[]
}

interface SupportMatrixCell {
  pass: number
  total: number
  gaps?: SupportMatrixGap[]
}

interface SupportMatrixSourceLink {
  file: string
  line: number
  url: string
}

interface SupportMatrixExample {
  fixture: string
  description: string
  url: string
  code?: string
}

interface SupportMatrixConstruct {
  total: number
  cells: Record<string, SupportMatrixCell>
  source?: SupportMatrixSourceLink
  example?: SupportMatrixExample
}

interface SupportMatrixLock {
  note: string
  knownLimitationLabel: string
  adapters: string[]
  kinds: Record<string, SupportMatrixConstruct>
  axes: Record<string, SupportMatrixConstruct>
}

const supportMatrix = supportMatrixLock as SupportMatrixLock

function escapeCell(text: string): string {
  return text.replace(/\|/g, '\\|')
}

/**
 * Neutralize Markdown emphasis/code metacharacters in free-form prose that
 * gets interpolated into a generated Markdown line — today only
 * `escapeNotOwed.reason`, which fixture authors write as ordinary English.
 *
 * Today's reasons happen to survive unescaped: they contain `/* @client *\/`,
 * whose asterisks sit next to whitespace and so are neither left- nor
 * right-flanking, so CommonMark won't open emphasis on them. That safety is
 * accidental and narrow — verified with the site's own `marked`, TWO such
 * occurrences in one paragraph DO pair up (`'/* @client <em>/' … '/</em> @client *\/'`),
 * and any future reason containing `*emphasis*` or a backtick renders as
 * markup rather than text. `reason` is prose owned by whoever writes the
 * fixture, so the renderer should not depend on what they happen to type.
 */
function escapeMarkdownProse(text: string): string {
  return text.replace(/([*_`[\]\\])/g, '\\$1')
}

/**
 * The two escape-state markers — same characters `packages/compat/src/report.ts`
 * uses for the CLI's own `--md` / `--render` output, so the docs page and
 * the CI job-summary table read identically. `ESCAPABLE_MARKER` decorates
 * the WORKS checkmark (`✓†`), not a diagnostic code: once a verified escape
 * exists the fixture works, so the code moves out of the cell into the
 * detail list below. `'debt'` is deliberately unmarked: a bare `BF101`
 * means refused, no escape yet.
 *
 * `NOT_OWED_MARKER` leads its code (`✗BF021`) rather than trailing it. The
 * distinction it carries is the sharpest one on the page — a bare code is
 * tracked work with a fix planned, a marked one is a permanent, deliberate
 * refusal — and as a trailing `‡` it sat one small glyph away from the
 * code it negated, at the end, where a scanning reader meets it last. A
 * leading `✗` separates the two at the first character instead.
 */
const ESCAPABLE_MARKER = '†'
const NOT_OWED_MARKER = '✗'

/** The marker LEADING a not-owed refusal's code (`''` for every other state). */
function notOwedPrefix(escape: FixtureEscapeState | undefined): string {
  return escape?.state === 'not-owed' ? NOT_OWED_MARKER : ''
}

/**
 * Deduped, sorted issue URLs as `#NNNN` links, falling back to the repo-
 * wide known-limitation label when none exist. Shared by `buildLegend`
 * (compat matrix, per diagnostic code) and the construct-support section
 * below (per gapped cell) so both link formats stay identical.
 */
function formatIssueLinks(issues: string[], fallbackLabel: string): string {
  // Dedupe + code-unit sort HERE (matching the lockfiles' issue ordering) so
  // both callers are deterministic from one place: `collectLegend` feeds
  // Set-insertion-ordered URLs, and the construct-support cells feed already-
  // flattened gap URLs — neither is pre-sorted at the call site.
  const unique = [...new Set(issues)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  if (unique.length === 0) return `[known limitation](${fallbackLabel})`
  return unique.map((url) => `[#${url.split('/').pop()}](${url})`).join(', ')
}

/** Render one matrix cell as a Markdown fragment. */
function cellMarkdown(cell: CompatCell | undefined): string {
  if (!cell) return '?'
  const diagnostics = cell.diagnostics ?? []
  if (cell.ok && diagnostics.length === 0) return '✓'
  if (diagnostics.length === 0) return cell.ok ? '✓' : '?'

  return diagnostics
    .map((d) => {
      const label = d.severity === 'warning' ? `⚠ ${d.code}` : d.code
      const firstIssue = d.issues?.[0]
      return firstIssue ? `[${label}](${firstIssue})` : label
    })
    .join('<br>')
}

/** Build the "N components × M adapters — X / Y cells compile clean" summary line. */
function buildSummary(componentNames: string[]): string {
  const adapters = compat.adapters
  const totalCells = componentNames.length * adapters.length
  let okCells = 0
  for (const name of componentNames) {
    for (const adapter of adapters) {
      if (compat.components[name]?.[adapter]?.ok) okCells++
    }
  }
  return `**${componentNames.length} components × ${adapters.length} adapters — ${okCells} / ${totalCells} cells compile clean**`
}

/**
 * The "Component" cell: the name linked to its public component page on
 * ui.barefootjs.dev when it has one, else to its source (`componentDocs`
 * is generated alongside the lock), else a plain code span.
 */
function componentLabelMarkdown(name: string, doc: ComponentDoc | undefined): string {
  const code = `\`${escapeCell(name)}\``
  const url = doc?.uiUrl ?? doc?.url
  return url ? `[${code}](${url})` : code
}

/** Build the Markdown table: one row per component, a description, then one column per adapter. */
function buildTable(componentNames: string[]): string {
  const adapters = compat.adapters
  const header = `| Component | Description | ${adapters.join(' | ')} |`
  const divider = `| --- | --- | ${adapters.map(() => '---').join(' | ')} |`
  const rows = componentNames.map((name) => {
    const doc = compat.componentDocs?.[name]
    const description = doc?.description ? escapeCell(doc.description) : '—'
    const cells = adapters.map((adapter) => cellMarkdown(compat.components[name]?.[adapter]))
    return `| ${componentLabelMarkdown(name, doc)} | ${description} | ${cells.join(' | ')} |`
  })
  return [header, divider, ...rows].join('\n')
}

/** Collect every distinct diagnostic code across all cells, with its deduped issue URLs and escape claims. */
function collectLegend(): { code: string; severity: CompatDiagnostic['severity']; issues: string[]; escapes: string[] }[] {
  const byCode = new Map<string, { severity: CompatDiagnostic['severity']; issues: Set<string>; escapes: Set<string> }>()

  for (const adapterMap of Object.values(compat.components)) {
    for (const cell of Object.values(adapterMap)) {
      for (const d of cell.diagnostics ?? []) {
        const entry = byCode.get(d.code) ?? { severity: d.severity, issues: new Set<string>(), escapes: new Set<string>() }
        for (const issue of d.issues ?? []) entry.issues.add(issue)
        for (const kind of d.escapes ?? []) entry.escapes.add(kind)
        byCode.set(d.code, entry)
      }
    }
  }

  return [...byCode.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([code, { severity, issues, escapes }]) => ({ code, severity, issues: [...issues], escapes: [...escapes] }))
}

/**
 * The error-codes reference entry for a diagnostic code (#2614 increment
 * 1). Generated from the code alone — `docs/core/advanced/error-codes.md`
 * carries an explicit `<a id="bf101">`-style anchor above each `### BFNNN`
 * heading precisely so this stays a computation rather than a committed
 * code→anchor map that could drift. The anchors are also independent of
 * the heading wording, so rewording a section cannot break these links.
 * `error-codes-anchors.test.ts` fails if a code reachable from the lock
 * has no anchor in the doc.
 */
export function errorCodeDocLink(code: string): string {
  return `/docs/advanced/error-codes#${code.toLowerCase()}`
}

function buildLegend(): string {
  const entries = collectLegend()
  if (entries.length === 0) {
    return `No diagnostics were reported — every component compiles cleanly on every adapter.`
  }

  return entries
    .map(({ code, severity, issues, escapes }) => {
      const label = severity === 'warning' ? `⚠ \`${code}\`` : `\`${code}\``
      const linked = `[${label}](${errorCodeDocLink(code)})`
      const parts = [formatIssueLinks(issues, compat.knownLimitationLabel)]
      const escapeText = formatEscapes(escapes)
      if (escapeText) parts.push(escapeText)
      return `- ${linked} — ${parts.join(' · ')}`
    })
    .join('\n')
}

/**
 * Render one fixture-conformance cell — the check mark answers "does it
 * work?" first: `✓` for clean, `✓${ESCAPABLE_MARKER}` for a refusal with a
 * verified working escape (it WORKS, given a `/* @client *\/` comment — no
 * diagnostic code shown; the suppressed code lives in the detail list
 * below), `≠` for a render divergence, and the diagnostic code (linked to
 * its tracking issue, led by \`${NOT_OWED_MARKER}\` when declared not owed)
 * for every other refusal — the two states that still mean "does not
 * work".
 */
function fixtureCellMarkdown(cell: FixtureDivergenceCell | undefined): string {
  if (!cell) return '✓'
  if (cell.kind === 'render') return '≠'
  if (cell.escape?.state === 'escapable') return `✓${ESCAPABLE_MARKER}`
  const codes = cell.codes ?? []
  const firstIssue = cell.issues?.[0]
  const label = codes.join(', ') || 'refused'
  const linked = firstIssue ? `[${label}](${firstIssue})` : label
  return `${notOwedPrefix(cell.escape)}${linked}`
}

/**
 * True when every adapter cell present on this fixture's row is a refusal
 * with a verified working escape — the fixture works on every adapter,
 * either as written or with a documented `/* @client *\/` comment, so it
 * doesn't need a row in the "needs attention" table. Mirrors
 * `rowWorksEverywhere` in `packages/compat/src/report.ts` (duplicated, not
 * imported — `site/core` has no dependency on `@barefootjs/compat`, see
 * this file's header).
 */
function fixtureWorksEverywhere(row: Record<string, FixtureDivergenceCell>): boolean {
  return Object.values(row).every((cell) => cell.kind === 'refusal' && cell.escape?.state === 'escapable')
}

/**
 * One `(fixture, adapter)` refusal's detail-list line — the prose
 * counterpart of the table cell. An escapable refusal leads with "works"
 * (the table's own framing) and still names the diagnostic code its
 * escape suppresses, plus a link to the twin fixture that proves it — the
 * code moved OUT of the table cell (`✓${ESCAPABLE_MARKER}`, not
 * `BF101${ESCAPABLE_MARKER}`) but stays legible here. A debt or not-owed
 * refusal leads with "refused" instead, since that's the honest answer
 * for those two states. Links the escape twin to its own source when
 * `fd.docs` happens to carry it (the CLI attaches docs for every escape
 * twin referenced by an `'escapable'` cell, not just the fixtures listed
 * in the table themselves).
 */
function refusalDetailText(cell: FixtureDivergenceCell, fd: FixtureDivergences): string {
  // Deliberately NOT `escapeCell`-escaped here — the composed text this
  // returns is escaped exactly once, at the point `buildFixtureDetails`
  // joins it into a Markdown line, same as every other fragment there.
  // Escaping twice would double-escape a literal `|` (`\|` → `\\|`).
  // Codes link to the error-codes reference (#2614): the detail list is
  // where a reader actually MEETS a refusal — the component legend below
  // is empty whenever every `ui/` component compiles clean, which is the
  // normal state — so a code shown here without a way to the guidance is
  // the exact gap this linking closes.
  const codes = (cell.codes ?? []).map((c) => `[\`${c}\`](${errorCodeDocLink(c)})`).join(', ')
  const escape = cell.escape
  if (escape?.state === 'escapable') {
    const twinDoc = fd.docs?.[escape.twin]
    const twinLabel = twinDoc?.url ? `[\`${escape.twin}\`](${twinDoc.url})` : `\`${escape.twin}\``
    return `works with a \`/* @client */\` comment — **verified escape** (${ESCAPABLE_MARKER}): ${twinLabel} compiles clean here, suppressing ${codes}`
  }
  if (escape?.state === 'not-owed') {
    return `refused at build time with ${codes} — **no escape owed** (${NOT_OWED_MARKER}): ${escapeMarkdownProse(escape.reason)}`
  }
  return `refused at build time with ${codes}`
}

/**
 * Per-fixture detail list for the fixtures the table actually shows:
 * adapters sharing an identical reason string are grouped onto one line, so
 * the common "same divergence everywhere" case reads as a single sentence
 * instead of nine copies.
 *
 * `fixtureIds` is the table's own row list, NOT every key in `fd.fixtures`.
 * The two are very different sizes — the table is filtered to fixtures
 * needing attention (4 of 18 today), and detailing the other 14 spent most
 * of the page explaining cells the reader was never shown, immediately
 * after the text told them those fixtures work. Their one useful fact
 * (which diagnostic the `/* @client *\/` comment silences) is kept, one
 * line each, by `buildEscapableSummary` below.
 */
function buildFixtureDetails(fd: FixtureDivergences, fixtureIds: string[]): string {
  const blocks: string[] = []
  for (const fixtureId of [...fixtureIds].sort()) {
    const row = fd.fixtures[fixtureId]
    const byText = new Map<string, string[]>()
    for (const adapterId of Object.keys(row).sort()) {
      const cell = row[adapterId]
      const text = cell.kind === 'refusal' ? refusalDetailText(cell, fd) : (cell.reason ?? 'rendered output diverges from the Hono reference')
      const adapters = byText.get(text) ?? []
      adapters.push(adapterId)
      byText.set(text, adapters)
    }
    const lines = [...byText.entries()].map(
      ([text, adapters]) => `  - ${adapters.map((a) => `\`${a}\``).join(', ')} — ${escapeCell(text)}`,
    )
    const doc = fd.docs?.[fixtureId]
    const heading = doc?.url ? `**[\`${fixtureId}\`](${doc.url})**` : `**\`${fixtureId}\`**`
    const summary = doc?.description ? ` — ${escapeCell(doc.description)}` : ''
    blocks.push(`- ${heading}${summary}\n${lines.join('\n')}`)
  }
  return blocks.join('\n')
}

/**
 * The folded-away half of the corpus, one line per fixture behind a
 * disclosure: fixtures that work on EVERY adapter, some only with a
 * `/* @client *\/` comment. They have no row in the table (nothing needs
 * attention), so per-adapter prose about them is detail for a cell the
 * reader never saw. What they DO raise — the headline says "14 of those
 * need a comment", and the reader wants to know which — is answered here:
 * the fixture, how many adapters need the comment there, and what it
 * silences. Collapsed rather than dropped so the answer stays on the page
 * without costing the four fixtures that need attention their prominence.
 */
function buildEscapableSummary(fd: FixtureDivergences, fixtureIds: string[]): string {
  if (fixtureIds.length === 0) return ''
  const lines = [...fixtureIds].sort().map((id) => {
    const row = fd.fixtures[id]
    // Only refusing adapters have a cell at all — a clean adapter is absent
    // — so the row's own size IS "how many adapters need the comment".
    const adapterIds = Object.keys(row)
    const codes = [...new Set(adapterIds.flatMap((a) => row[a].codes ?? []))].sort()
    const doc = fd.docs?.[id]
    const label = doc?.url ? `[\`${escapeCell(id)}\`](${doc.url})` : `\`${escapeCell(id)}\``
    const codeLinks = codes.map((c) => `[\`${c}\`](${errorCodeDocLink(c)})`).join(', ')
    const adapterCount = `${adapterIds.length} adapter${adapterIds.length === 1 ? '' : 's'}`
    return `- ${label} — ${adapterCount}, suppressing ${codeLinks}`
  })
  return `
<details>
<summary>The ${fixtureIds.length} fixtures that need a <code>/* @client */</code> comment — which diagnostic each silences</summary>

${lines.join('\n')}

</details>
`
}

/**
 * A representative diagnostic code for the legend's examples, read out of
 * the table's OWN cells rather than hardcoded. The legend leads each line
 * with the literal thing a reader sees in a cell (`BF021`, `BF021${NOT_OWED_MARKER}`) — a
 * hardcoded example goes stale silently the moment the pinned code moves,
 * naming a code that appears nowhere above it. Falls back to the bare
 * shape when no cell is in that state, which is the honest answer: the
 * state exists, nothing in this table is currently in it.
 */
function exampleRefusalCode(
  fd: FixtureDivergences,
  fixtureIds: string[],
  adapters: string[],
  want: 'debt' | 'not-owed',
): string {
  for (const id of fixtureIds) {
    for (const adapter of adapters) {
      const cell = fd.fixtures[id]?.[adapter]
      if (!cell || cell.kind !== 'refusal') continue
      // An absent escape state is debt by the same reading `fixtureCellMarkdown`
      // gives it — a refusal with no verified escape and no declared reason.
      if ((cell.escape?.state ?? 'debt') !== want) continue
      const code = cell.codes?.[0]
      if (code) return code
    }
  }
  return 'BF…'
}

/** The render-conformance section: fixture × adapter table (needing-attention rows only) + detail list. */
function buildFixtureSection(): string {
  const fd = compat.fixtureDivergences
  if (!fd || Object.keys(fd.fixtures).length === 0) return ''

  const allFixtureIds = Object.keys(fd.fixtures)
  const fullyEscapableIds = allFixtureIds.filter((id) => fixtureWorksEverywhere(fd.fixtures[id]))
  const needsAttentionIds = allFixtureIds.filter((id) => !fixtureWorksEverywhere(fd.fixtures[id])).sort()
  const adapters = compat.adapters
  const cleanCount = fd.totalFixtures - allFixtureIds.length
  const worksEverywhereCount = cleanCount + fullyEscapableIds.length
  const debtExample = exampleRefusalCode(fd, needsAttentionIds, adapters, 'debt')
  const notOwedExample = exampleRefusalCode(fd, needsAttentionIds, adapters, 'not-owed')

  const header = `| Fixture | ${adapters.join(' | ')} |`
  const divider = `| --- | ${adapters.map(() => '---').join(' | ')} |`
  const rows = needsAttentionIds.map((id) => {
    const doc = fd.docs?.[id]
    const label = doc?.url ? `[\`${escapeCell(id)}\`](${doc.url})` : `\`${escapeCell(id)}\``
    const cells = adapters.map((adapter) => fixtureCellMarkdown(fd.fixtures[id]?.[adapter]))
    return `| ${label} | ${cells.join(' | ')} |`
  })

  return `
## Render Conformance (fixture corpus)

The component matrix above is **compile-time only**. This section answers the question that actually matters: **does the construct work**, on each adapter's real backend (Go, Ruby, Perl, PHP, Python, Rust), byte-compared against the Hono reference — not just whether it compiles. A construct works either **as written** (\`✓\`) or with a documented \`/* @client */\` comment (\`✓${ESCAPABLE_MARKER}\`, a verified, supported escape — most refusals have one). Fixtures absent from the table below work on every adapter — most as written, some via that documented escape; the headline says how many of each.

The table lists only fixtures that need attention: at least one adapter where nothing works today. Each cell's meaning is in the legend below it; diagnostic codes link to their known-limitation issue, and the reason a code is led by \`${NOT_OWED_MARKER}\` is in that fixture's detail entry. Escape verification is per adapter, so the same fixture can show \`✓${ESCAPABLE_MARKER}\` in one column and a code needing attention in another — see [\`escape-coverage.ts\`](https://github.com/piconic-ai/barefootjs/blob/main/packages/compat/src/escape-coverage.ts).

**${worksEverywhereCount} / ${fd.totalFixtures} fixtures work on every adapter** (${fullyEscapableIds.length} of those need a \`/* @client */\` comment on at least one adapter). The ${needsAttentionIds.length} below need attention:

${[header, divider, ...rows].join('\n')}

**✓ Works**

- \`✓\` — as written
- \`✓${ESCAPABLE_MARKER}\` — with a \`/* @client */\` comment (the details below say which diagnostic it silences)

**☐ TODO** — fix planned, issue linked

- \`≠\` — compiles, but renders differently from the Hono reference
- \`${debtExample}\` — a bare diagnostic code: build error, no escape yet

**${NOT_OWED_MARKER} Doesn't work** — by design, not a gap

- \`${NOT_OWED_MARKER}${notOwedExample}\` — a code led by \`${NOT_OWED_MARKER}\`: refused on purpose, no escape will ever be offered (why: in the details below)
${buildEscapableSummary(fd, fullyEscapableIds)}
### Divergence details

Per adapter, for the ${needsAttentionIds.length} fixtures in the table above.

${buildFixtureDetails(fd, needsAttentionIds)}
`
}

/**
 * Render one construct-support cell as `pass/total`, plus linked tracking
 * issues when the construct has gaps on this adapter. Deduped across every
 * gapped fixture in the cell — a common case is several fixtures gapped by
 * the same pinned diagnostic, which would otherwise repeat its issue link.
 */
function supportCellMarkdown(cell: SupportMatrixCell | undefined): string {
  if (!cell) return '?'
  const ratio = `${cell.pass}/${cell.total}`
  const gaps = cell.gaps ?? []
  if (gaps.length === 0) return ratio
  // `formatIssueLinks` dedupes + sorts, so just flatten every gapped
  // fixture's issues here (several fixtures gapped by the same diagnostic
  // repeat its URL — the helper collapses them).
  const issues = gaps.flatMap((gap) => gap.issues)
  return `${ratio} (${formatIssueLinks(issues, supportMatrix.knownLimitationLabel)})`
}

/**
 * The "Construct" cell: the label linked to the construct's exemplar
 * conformance fixture — a small self-contained component showing the
 * case in real code — falling back to the definition-site permalink
 * (where the construct is registered in the compiler) for constructs
 * with no covering fixture yet (`total: 0` rows). See the "Data Source"
 * section below for how these stay in sync as the source moves.
 */
function constructLabelMarkdown(construct: SupportMatrixConstruct | undefined, name: string): string {
  const code = `\`${escapeCell(name)}\``
  const url = construct?.example?.url ?? construct?.source?.url
  return url ? `[${code}](${url})` : code
}

/**
 * The "Example" cell: the extracted code snippet (when one exists) with
 * the exemplar fixture's description under it. A snippet containing a
 * backtick (template literals) uses a double-backtick code span, per
 * CommonMark.
 */
function exampleCellMarkdown(construct: SupportMatrixConstruct | undefined): string {
  const example = construct?.example
  if (!example) return '—'
  const description = escapeCell(example.description)
  if (!example.code) return description
  const code = escapeCell(example.code)
  const span = code.includes('`') ? `\`\` ${code} \`\`` : `\`${code}\``
  return `${span}<br>${description}`
}

/** One `construct × adapter` table — shared by the "By kind" and "By axis" tables. */
function buildSupportTable(records: Record<string, SupportMatrixConstruct>): string {
  const adapters = supportMatrix.adapters
  const names = Object.keys(records).sort()
  const header = `| Construct | Example | ${adapters.join(' | ')} |`
  const divider = `| --- | --- | ${adapters.map(() => '---').join(' | ')} |`
  const rows = names.map((name) => {
    const cells = adapters.map((adapter) => supportCellMarkdown(records[name]?.cells[adapter]))
    return `| ${constructLabelMarkdown(records[name], name)} | ${exampleCellMarkdown(records[name])} | ${cells.join(' | ')} |`
  })
  return [header, divider, ...rows].join('\n')
}

/**
 * Construct-level drill-down: every `ParsedExpr` kind (`identifier`,
 * `call`, `literal`, ...) and every finer-grained axis within a kind
 * (`binary:===`, `literal:string`, `array-method:includes`, ...) against
 * the shared conformance corpus. Complements the component matrix above —
 * that one answers "does this whole component compile clean", this one
 * answers "of the fixtures that exercise construct X, how many are clean".
 */
function buildSupportMatrixSection(): string {
  return `
## Construct Support (kind × axis)

${supportMatrix.note}

**Read this as a ratio, not a binary.** \`conformancePins\` and \`renderDivergences\` are attributed to a whole **fixture** (a component), not to the individual construct — a gapped fixture is usually a complex component that happens to exercise many common kinds and axes alongside the one shape it exists to pin down. A construct showing \`137/138\` has exactly one gapped fixture contributing to it, not 137 broken cases. A construct with \`total: 0\` (currently just \`regex\`) has no fixture exercising it yet.

Each construct name links to a conformance fixture exercising it — a small self-contained component showing the case in real code — and the **Example** column is that fixture's description. Constructs with no covering fixture yet link to where they're registered in the compiler instead.

### By kind

${buildSupportTable(supportMatrix.kinds)}

### By axis

${buildSupportTable(supportMatrix.axes)}
`
}

function buildMarkdown(): string {
  const componentNames = Object.keys(compat.components).sort()
  const summary = buildSummary(componentNames)
  const table = buildTable(componentNames)
  const legend = buildLegend()
  const fixtureSection = buildFixtureSection()
  const supportMatrixSection = buildSupportMatrixSection()

  return `# ${TITLE}

This matrix reports **compile-time** compatibility: for every component under \`ui/\`, whether \`compileJSX\` plus each adapter's \`generate()\` step produces diagnostics-free output. ${compat.note}

${summary}

## Matrix

Each component name links to its [component page](https://ui.barefootjs.dev/components) (or its source, for components without one); the **Description** column says what it is.

${table}

## Legend

Each diagnostic code below links to the known-limitation issue(s) tracking it. Codes with no linked issue fall back to the repo-wide [\`known-limitation\`](${compat.knownLimitationLabel}) label.

${legend}
${fixtureSection}
${supportMatrixSection}
## Data Source

This table is generated from the committed [\`ui/compat.lock.json\`](https://github.com/piconic-ai/barefootjs/blob/main/ui/compat.lock.json), regenerated with \`bun run compat:lock\` and drift-checked in CI. Render-level divergences are declared per adapter in \`packages/adapter-*/src/render-divergences.ts\` (each adapter's conformance suite derives its skip list from the same declaration, so this page and the tests cannot drift apart). Tracked limitations carry the [\`known-limitation\`](${compat.knownLimitationLabel}) label.

Component and fixture descriptions are computed into the same lock at regen time ([\`component-docs.ts\`](https://github.com/piconic-ai/barefootjs/blob/main/packages/compat/src/component-docs.ts)) — component copy is taken from the public component page's own \`description\` (falling back to the \`ui/registry.json\` catalogue one-liner, then the component's JSDoc tagline), and the component name links to that page when one exists; fixture descriptions come from the corpus itself. All of it is drift-checked with everything else and can't go stale independently.

The construct-support section above is generated from the committed [\`ui/support-matrix.lock.json\`](https://github.com/piconic-ai/barefootjs/blob/main/ui/support-matrix.lock.json), regenerated with \`bun run support-matrix:lock\` and drift-checked in CI alongside the component matrix. Each construct's fixture link and example description are computed the same way — the exemplar is mechanically chosen as the most narrowly targeted covering fixture ([\`construct-examples.ts\`](https://github.com/piconic-ai/barefootjs/blob/main/packages/compat/src/construct-examples.ts)), and definition-site fallback links come from a TS AST walk over the compiler's construct catalogues ([\`construct-source-links.ts\`](https://github.com/piconic-ai/barefootjs/blob/main/packages/compat/src/construct-source-links.ts)) — so they are regenerated and drift-checked on the same schedule: a link can't silently go stale, because moving the code it points at changes what the next regen commits, and CI fails if that regen was forgotten.

Every issue link on this page is freshness-checked on a schedule (\`bun run compat:issues\`, the [\`compat-issue-freshness\`](https://github.com/piconic-ai/barefootjs/blob/main/.github/workflows/compat-issue-freshness.yml) workflow): if a referenced issue is closed while its pin still points at it, an alert issue is opened automatically so the link is re-pointed or removed — the matrix cannot silently link a live limitation to a completed ticket.
`
}

export function registerCompatMatrixRoutes(app: Hono): void {
  const markdown = buildMarkdown()

  app.get(`/${SLUG}`, async (c) => {
    const parsed = await renderMarkdown(markdown)
    const navLinks = getDocsNavLinks(SLUG)

    return c.render(
      <div dangerouslySetInnerHTML={{ __html: parsed.html }} />,
      {
        title: TITLE,
        description: DESCRIPTION,
        slug: SLUG,
        toc: parsed.toc,
        prev: navLinks.prev,
        next: navLinks.next,
      },
    )
  })

  app.get(`/${SLUG}.md`, (c) => {
    c.header('Content-Type', 'text/markdown; charset=utf-8')
    return c.body(markdown)
  })
}
